def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'

    last_opp = history[-1][1]
    last_mine = history[-1][0]

    if last_opp == 'C':
        return 'C'

    # last_opp == 'D'
    opp_def_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_def_streak += 1
        else:
            break

    if opp_def_streak >= 6:
        return 'D'

    mutual_def_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D' and history[i][1] == 'D':
            mutual_def_streak += 1
        else:
            break

    if mutual_def_streak >= 2:
        return 'C'

    if last_mine == 'C':
        if opp_def_streak == 1:
            return 'C'
        else:
            return 'D'
    else:
        return 'D'
